//! Kotlin bindings for the Beep client, generated by UniFFI.
//!
//! `BeepClient` has one suspend function per request. It binds one iroh
//! endpoint for its lifetime, connects on first use, and reconnects after the
//! connection drops or closes for being idle. While no connection is open,
//! the server dials the endpoint to deliver notices.

use beep_proto::{
    AnswerApproval, ApiError, AppIntegration, AppPermissions, ApprovalDecision, Call, CancelRun,
    Chat, ClearMemories, ConnectApp, ConnectLink, CreateCron, Cron, DeleteCron, DeleteMemory,
    DeleteSession, DeleteSessions, DeleteTurn, DeleteTurnsFrom, DeviceAnswer, DeviceResult,
    DisconnectApp, Event, ExistingSessions, FinishAppAuth, ForegroundApp, GetAppPermissions,
    GetEvents, GetModels, GetRun, GetSession, Health, HistoryEntry, ListApps, ListCrons,
    ListMemories, ListSessions, Memory, Models, Notice, PermissionLevel, PinSession,
    PromptSuggestions, ReasoningLevel, RegisterDevice, RenameSession, Run, RunCron, SearchSessions,
    Session, SessionMatch, SetAppPermissions, SetModel, SetThinking, StartAppAuth, Stream,
    SuggestPrompts, ToggleCron, UnregisterDevice, UpdateCron, UpdateLocation, UpdateMemory,
    client::{Client, Node, OnNotice, Replies},
    names::username,
};
use iroh::{EndpointId, SecretKey};
use serde::{Deserialize, Serialize};
use std::{
    future::Future,
    sync::{Arc, Mutex, PoisonError},
    time::Duration,
};
use tokio::{
    sync::{Mutex as AsyncMutex, OnceCell},
    time::timeout,
};
use uuid::Uuid;

uniffi::setup_scaffolding!();
uniffi::use_remote_type!(beep_proto::ReasoningLevel);

const CONNECT_TIMEOUT: Duration = Duration::from_secs(20);
const CALL_TIMEOUT: Duration = Duration::from_secs(45);

/// Field names avoid `message`, which Kotlin exceptions already define.
#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum BeepError {
    #[error("{reason}")]
    BadRequest { reason: String },
    #[error("not found")]
    NotFound,
    #[error("{reason}")]
    Conflict { reason: String },
    #[error("unauthorized")]
    Unauthorized,
    #[error("server error")]
    Internal,
    #[error("{reason}")]
    Connection { reason: String },
}

impl From<ApiError> for BeepError {
    fn from(e: ApiError) -> Self {
        match e {
            ApiError::BadRequest { message } => Self::BadRequest { reason: message },
            ApiError::NotFound {} => Self::NotFound,
            ApiError::Conflict { message } => Self::Conflict { reason: message },
            ApiError::Unauthorized {} => Self::Unauthorized,
            ApiError::Internal {} => Self::Internal,
        }
    }
}

impl From<anyhow::Error> for BeepError {
    fn from(e: anyhow::Error) -> Self {
        match e.downcast::<ApiError>() {
            Ok(api) => api.into(),
            Err(e) => Self::Connection {
                reason: format!("{e:#}"),
            },
        }
    }
}

fn bad_request(message: impl Into<String>) -> BeepError {
    BeepError::BadRequest {
        reason: message.into(),
    }
}

async fn timed<T>(
    limit: Duration,
    what: &str,
    fut: impl Future<Output = anyhow::Result<T>>,
) -> Result<T, BeepError> {
    match timeout(limit, fut).await {
        Ok(result) => Ok(result?),
        Err(_) => Err(BeepError::Connection {
            reason: format!("{what} timed out"),
        }),
    }
}

fn secret_key(bytes: &[u8]) -> Result<SecretKey, BeepError> {
    let bytes: &[u8; 32] = bytes
        .try_into()
        .map_err(|_| bad_request("an identity is 32 bytes"))?;
    Ok(SecretKey::from_bytes(bytes))
}

/// A new random identity, as `BeepClient::new` takes it.
#[uniffi::export]
pub fn new_identity() -> Vec<u8> {
    SecretKey::generate().to_bytes().to_vec()
}

/// The settings lists the phone last fetched, kept to show at once while it
/// fetches them again. A list is `None` until the phone first fetched it.
#[derive(uniffi::Record, Serialize, Deserialize, Default)]
pub struct ListCache {
    pub memories: Option<Vec<Memory>>,
    pub crons: Option<Vec<Cron>>,
    pub apps: Option<Vec<AppIntegration>>,
    pub models: Option<Models>,
}

/// `cache` as bytes for the phone to save.
#[uniffi::export]
pub fn encode_list_cache(cache: ListCache) -> Vec<u8> {
    // Plain records and lists, which msgpack always encodes.
    rmp_serde::to_vec(&cache).unwrap_or_default()
}

/// The cache `encode_list_cache` saved, or an empty one when it was saved
/// by a build whose records differ.
#[uniffi::export]
pub fn decode_list_cache(bytes: Vec<u8>) -> ListCache {
    rmp_serde::from_slice(&bytes).unwrap_or_default()
}

/// The readable name of `identity`, such as `mega-fox-trot`.
#[uniffi::export]
pub fn identity_name(identity: Vec<u8>) -> Result<String, BeepError> {
    Ok(username(&secret_key(&identity)?.public()))
}

/// Gets the notices the server sends. Returns false if it could not show
/// one, and the server sends it again later.
#[uniffi::export(with_foreign)]
pub trait NoticeListener: Send + Sync {
    fn on_notice(&self, notice: Notice) -> bool;
}

type Listener = Arc<Mutex<Option<Arc<dyn NoticeListener>>>>;

#[derive(uniffi::Object)]
pub struct BeepClient {
    server: EndpointId,
    /// Who this phone is to the server. Its `Debug` prints nothing.
    identity: SecretKey,
    listener: Listener,
    node: OnceCell<Node>,
    client: AsyncMutex<Option<Arc<Client>>>,
}

impl BeepClient {
    async fn node(&self) -> Result<&Node, BeepError> {
        self.node
            .get_or_try_init(|| async {
                let listener = self.listener.clone();
                let on_notice: OnNotice = Arc::new(move |notice| {
                    // Cloned out so Kotlin runs without the lock held.
                    let listener = listener
                        .lock()
                        .unwrap_or_else(PoisonError::into_inner)
                        .clone();
                    listener.is_some_and(|l| l.on_notice(notice))
                });
                let bind = Node::bind(self.identity.clone(), self.server, on_notice);
                timed(CONNECT_TIMEOUT, "bind", bind).await
            })
            .await
    }

    async fn client(&self) -> Result<Arc<Client>, BeepError> {
        let node = self.node().await?;
        let mut cached = self.client.lock().await;
        if let Some(client) = cached.as_ref().filter(|c| !c.is_closed()) {
            return Ok(client.clone());
        }
        let client = Arc::new(timed(CONNECT_TIMEOUT, "connect", node.connect()).await?);
        *cached = Some(client.clone());
        Ok(client)
    }

    async fn call<R: Call>(&self, request: R) -> Result<R::Reply, BeepError> {
        let client = self.client().await?;
        timed(CALL_TIMEOUT, "request", client.call(&request)).await
    }

    async fn stream<R: Stream>(&self, request: R) -> Result<Replies<R::Reply>, BeepError> {
        let client = self.client().await?;
        timed(CALL_TIMEOUT, "request", client.stream(&request)).await
    }
}

#[uniffi::export(async_runtime = "tokio")]
impl BeepClient {
    /// `node_id` is the server's iroh public key. `identity` is this user's
    /// 32 byte iroh secret key; see `new_identity`.
    #[uniffi::constructor]
    pub fn new(node_id: String, identity: Vec<u8>) -> Result<Arc<Self>, BeepError> {
        let server: EndpointId = node_id
            .trim()
            .parse()
            .map_err(|_| bad_request("invalid node ID"))?;
        Ok(Arc::new(Self {
            server,
            identity: secret_key(&identity)?,
            listener: Arc::default(),
            node: OnceCell::new(),
            client: AsyncMutex::new(None),
        }))
    }

    /// Binds the endpoint, if not yet bound, and sends notices to `listener`
    /// from now on. The server can then reach this phone with no connection
    /// open.
    pub async fn listen(&self, listener: Arc<dyn NoticeListener>) -> Result<(), BeepError> {
        *self.listener.lock().unwrap_or_else(PoisonError::into_inner) = Some(listener);
        self.node().await?;
        Ok(())
    }

    /// Call when the phone's network changes. Android gives iroh no way to
    /// watch for this itself.
    pub async fn network_changed(&self) {
        if let Some(node) = self.node.get() {
            node.network_change().await;
        }
    }

    /// True while a connection to the server is open, so a request now
    /// costs no new handshake.
    pub async fn is_connected(&self) -> bool {
        let cached = self.client.lock().await;
        cached.as_ref().is_some_and(|c| !c.is_closed())
    }

    pub async fn health(&self) -> Result<(), BeepError> {
        self.call(Health {}).await
    }

    /// Starts a run and streams its events, starting with `RunStarted`.
    /// `session_id` and `request_id` are UUIDs. Resending the same
    /// `request_id` follows the existing run. `model` runs this one turn on
    /// another model; only admins may set it.
    pub async fn chat(
        &self,
        session_id: String,
        request_id: String,
        message: String,
        images: Vec<String>,
        foreground: Option<ForegroundApp>,
        model: Option<String>,
    ) -> Result<Arc<EventStream>, BeepError> {
        let uuid = |s: &str| Uuid::parse_str(s).map_err(|_| bad_request("invalid UUID"));
        let chat = Chat {
            session_id: uuid(&session_id)?,
            request_id: uuid(&request_id)?,
            message,
            images,
            foreground,
            model,
        };
        let replies = self.stream(chat).await?;
        Ok(Arc::new(EventStream(AsyncMutex::new(replies))))
    }

    pub async fn get_run(&self, id: String) -> Result<Run, BeepError> {
        self.call(GetRun { id }).await
    }

    pub async fn cancel_run(&self, id: String) -> Result<(), BeepError> {
        self.call(CancelRun { id }).await
    }

    /// Resumes a run's events after `after`, the last `seq` seen. Like `chat`,
    /// the stream ends when the run finishes or the server's window closes.
    pub async fn events(&self, run_id: String, after: i64) -> Result<Arc<EventStream>, BeepError> {
        let replies = self.stream(GetEvents { run_id, after }).await?;
        Ok(Arc::new(EventStream(AsyncMutex::new(replies))))
    }

    pub async fn device_result(
        &self,
        run_id: String,
        query_id: String,
        answer: DeviceAnswer,
    ) -> Result<bool, BeepError> {
        self.call(DeviceResult {
            run_id,
            query_id,
            answer,
        })
        .await
    }

    pub async fn list_sessions(&self) -> Result<Vec<Session>, BeepError> {
        self.call(ListSessions {}).await
    }

    /// The chats where the user or Beep wrote `query`, newest first.
    pub async fn search_sessions(&self, query: String) -> Result<Vec<SessionMatch>, BeepError> {
        self.call(SearchSessions { query }).await
    }

    /// The ones of `ids` the server still has.
    pub async fn existing_sessions(&self, ids: Vec<String>) -> Result<Vec<String>, BeepError> {
        self.call(ExistingSessions { ids }).await
    }

    /// Removes the turn whose user message has `timestamp`, with its reply
    /// and tool calls, and with `onward` every turn after it. Fails while
    /// the chat has a run.
    pub async fn delete_turn(
        &self,
        session_id: String,
        timestamp: i64,
        onward: bool,
    ) -> Result<(), BeepError> {
        if onward {
            self.call(DeleteTurnsFrom {
                session_id,
                timestamp,
            })
            .await
        } else {
            self.call(DeleteTurn {
                session_id,
                timestamp,
            })
            .await
        }
    }

    pub async fn get_session(&self, id: String) -> Result<Vec<HistoryEntry>, BeepError> {
        self.call(GetSession { id }).await
    }

    pub async fn rename_session(&self, id: String, title: String) -> Result<(), BeepError> {
        self.call(RenameSession { id, title }).await
    }

    pub async fn delete_session(&self, id: String) -> Result<(), BeepError> {
        self.call(DeleteSession { id }).await
    }

    /// Returns how many of the sessions were deleted.
    pub async fn delete_sessions(&self, ids: Vec<String>) -> Result<u64, BeepError> {
        self.call(DeleteSessions { ids }).await
    }

    pub async fn pin_session(&self, id: String, pinned: bool) -> Result<(), BeepError> {
        self.call(PinSession { id, pinned }).await
    }

    pub async fn list_memories(&self) -> Result<Vec<Memory>, BeepError> {
        self.call(ListMemories {}).await
    }

    pub async fn delete_memory(&self, id: String) -> Result<(), BeepError> {
        self.call(DeleteMemory { id }).await
    }

    pub async fn update_memory(&self, id: String, content: String) -> Result<(), BeepError> {
        self.call(UpdateMemory { id, content }).await
    }

    /// Returns how many memories were deleted.
    pub async fn clear_memories(&self) -> Result<u64, BeepError> {
        self.call(ClearMemories {}).await
    }

    pub async fn list_crons(&self) -> Result<Vec<Cron>, BeepError> {
        self.call(ListCrons {}).await
    }

    pub async fn create_cron(
        &self,
        label: String,
        prompt: String,
        schedule: String,
    ) -> Result<String, BeepError> {
        self.call(CreateCron {
            label,
            prompt,
            schedule,
        })
        .await
    }

    pub async fn toggle_cron(&self, id: String) -> Result<bool, BeepError> {
        self.call(ToggleCron { id }).await
    }

    pub async fn delete_cron(&self, id: String) -> Result<(), BeepError> {
        self.call(DeleteCron { id }).await
    }

    /// Runs a cron now and returns the session the run went to.
    pub async fn run_cron(&self, id: String) -> Result<String, BeepError> {
        self.call(RunCron { id }).await
    }

    pub async fn update_cron(
        &self,
        id: String,
        enabled: Option<bool>,
        label: Option<String>,
        schedule: Option<String>,
    ) -> Result<(), BeepError> {
        self.call(UpdateCron {
            id,
            enabled,
            label,
            schedule,
        })
        .await
    }

    pub async fn register_device(
        &self,
        device_id: String,
        fcm_token: String,
    ) -> Result<(), BeepError> {
        self.call(RegisterDevice {
            device_id,
            fcm_token,
        })
        .await
    }

    pub async fn unregister_device(&self, device_id: String) -> Result<(), BeepError> {
        self.call(UnregisterDevice { device_id }).await
    }

    pub async fn update_location(
        &self,
        latitude: f64,
        longitude: f64,
        accuracy: f64,
        timezone: String,
        place: Option<String>,
    ) -> Result<(), BeepError> {
        self.call(UpdateLocation {
            latitude,
            longitude,
            accuracy,
            timezone,
            place,
        })
        .await
    }

    /// The curated app list with each app's connection state.
    pub async fn list_apps(&self) -> Result<Vec<AppIntegration>, BeepError> {
        self.call(ListApps {}).await
    }

    /// An OAuth link to open in the browser to connect `slug`.
    pub async fn connect_app(&self, slug: String) -> Result<ConnectLink, BeepError> {
        self.call(ConnectApp { slug }).await
    }

    pub async fn disconnect_app(&self, slug: String) -> Result<(), BeepError> {
        self.call(DisconnectApp { slug }).await
    }

    /// What Beep may do in `slug`, and which of its actions act.
    pub async fn get_app_permissions(&self, slug: String) -> Result<AppPermissions, BeepError> {
        self.call(GetAppPermissions { slug }).await
    }

    /// The models this user can pick for their turns. Empty unless they are
    /// an admin.
    pub async fn get_models(&self) -> Result<Models, BeepError> {
        self.call(GetModels {}).await
    }

    /// Picks the model for this user's turns, by `ModelChoice::id`.
    pub async fn set_model(&self, id: String) -> Result<Models, BeepError> {
        self.call(SetModel { id }).await
    }

    /// Picks how long the model reasons on this user's turns.
    pub async fn set_thinking(&self, level: ReasoningLevel) -> Result<Models, BeepError> {
        self.call(SetThinking { level }).await
    }

    /// `allowed` names, by tool, the actions that run without asking.
    pub async fn set_app_permissions(
        &self,
        slug: String,
        level: PermissionLevel,
        allowed: Vec<String>,
    ) -> Result<(), BeepError> {
        self.call(SetAppPermissions {
            slug,
            level,
            allowed,
        })
        .await
    }

    /// Answers a tool call the session stopped on, and returns the run that
    /// resumes it. Answering again returns the same run.
    pub async fn answer_approval(
        &self,
        session_id: String,
        query_id: String,
        decision: ApprovalDecision,
    ) -> Result<Run, BeepError> {
        let session_id = Uuid::parse_str(&session_id).map_err(|_| bad_request("invalid UUID"))?;
        self.call(AnswerApproval {
            session_id,
            query_id,
            decision,
        })
        .await
    }

    /// Starts OAuth for an app whose provider redirects only to localhost.
    /// The app listens on `redirect_uri` and opens the returned URL.
    pub async fn start_app_auth(
        &self,
        slug: String,
        redirect_uri: String,
    ) -> Result<ConnectLink, BeepError> {
        self.call(StartAppAuth { slug, redirect_uri }).await
    }

    /// Passes the redirect's query parameters back to the server.
    pub async fn finish_app_auth(
        &self,
        slug: String,
        code: String,
        state: String,
        issuer: Option<String>,
    ) -> Result<(), BeepError> {
        self.call(FinishAppAuth {
            slug,
            code,
            state,
            issuer,
        })
        .await
    }

    /// Conversation starters for the empty chat. Always four.
    /// `refresh` asks for a new set instead of the server's cached one.
    pub async fn suggest_prompts(&self, refresh: bool) -> Result<PromptSuggestions, BeepError> {
        self.call(SuggestPrompts { refresh }).await
    }
}

#[derive(uniffi::Object)]
pub struct EventStream(AsyncMutex<Replies<Event>>);

#[uniffi::export(async_runtime = "tokio")]
impl EventStream {
    /// Next event, `null` once the stream ends.
    pub async fn next(&self) -> Result<Option<Event>, BeepError> {
        Ok(self.0.lock().await.next().await?)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn list_cache_round_trips_and_forgets_what_it_cannot_read() {
        let cache = ListCache {
            models: Some(Models {
                choices: Vec::new(),
                selected: "model-a".into(),
                thinking: ReasoningLevel::Medium,
            }),
            ..ListCache::default()
        };
        let decoded = decode_list_cache(encode_list_cache(cache));
        assert_eq!(
            decoded.models.map(|m| m.selected).as_deref(),
            Some("model-a")
        );
        assert!(decoded.memories.is_none());
        assert!(decode_list_cache(vec![0xc1]).models.is_none());
    }
}
